package local.spatialclient;
import java.util.*;import java.nio.file.*;import java.util.concurrent.atomic.AtomicReference;
import net.minecraft.client.*;import net.minecraft.resources.Identifier;import net.minecraft.world.entity.*;import net.minecraft.world.entity.ai.attributes.*;import net.minecraft.world.effect.*;import net.minecraft.world.item.*;
import net.neoforged.api.distmarker.Dist;import net.neoforged.fml.common.Mod;import net.neoforged.neoforge.common.NeoForge;import net.neoforged.neoforge.client.event.ClientTickEvent;
import net.spell_engine.internals.*;import net.spell_engine.internals.container.*;import net.spell_engine.internals.casting.*;import net.spell_engine.internals.target.*;import net.valhaimerd.orboblivioncompat.*;import net.puffish.skillsmod.api.*;
@Mod(value="spatial_client_probe",dist=Dist.CLIENT) public class BatchClientProbe {
 int ticks,phase,at;boolean pending,hidden;final List<String> lines=new ArrayList<>();final AtomicReference<Throwable> error=new AtomicReference<>();
 net.puffish.skillsmod.client.gui.SkillsScreen screen;
 public BatchClientProbe(){NeoForge.EVENT_BUS.addListener(this::tick);NeoForge.EVENT_BUS.addListener(this::opening);}
 void opening(net.neoforged.neoforge.client.event.ScreenEvent.Opening e){if(e.getNewScreen() instanceof net.puffish.skillsmod.client.gui.SkillsScreen s)screen=s;}
 void check(boolean ok,String label){lines.add((ok?"PASS ":"FAIL ")+label);if(!ok)throw new AssertionError(label);}
 void server(java.util.function.Consumer<net.minecraft.server.level.ServerPlayer> job){var mc=Minecraft.getInstance();pending=true;mc.getSingleplayerServer().execute(()->{try{job.accept(mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID()));}catch(Throwable e){error.set(e);}finally{pending=false;}});}
 void step(){phase++;at=ticks;}
 void finish(){if(phase==99)return;phase=99;var mc=Minecraft.getInstance();try{Files.write(mc.gameDirectory.toPath().resolve("spatial-client-checks.txt"),lines);Files.writeString(mc.gameDirectory.toPath().resolve("spatial-client-result.txt"),lines.stream().anyMatch(s->s.startsWith("FAIL"))?"FAIL":"PASS");}catch(Exception ignored){}mc.stop();}
 void view(float scale,int x,int y)throws Exception{var field=screen.getClass().getDeclaredField("optActiveCategoryData");field.setAccessible(true);var category=(net.puffish.skillsmod.client.data.ClientCategoryData)((Optional<?>)field.get(screen)).orElseThrow();category.setScale(scale);category.setX(x);category.setY(y);}
 void tick(ClientTickEvent.Post event){var mc=Minecraft.getInstance();ticks++;if(!hidden&&mc.getWindow()!=null){org.lwjgl.glfw.GLFW.glfwHideWindow(mc.getWindow().handle());hidden=true;mc.options.pauseOnLostFocus=false;}if(phase==99)return;try{
  if(error.get()!=null)throw new RuntimeException(error.get());if(pending||mc.player==null||mc.level==null||mc.getSingleplayerServer()==null)return;if(ticks-at>2400)throw new AssertionError("Timeout phase"+phase);if(ticks-at<35)return;
  if(phase==0){server(p->{p.removeAllEffects();p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);p.getInventory().clearContent();p.getAttribute(Attributes.MAX_HEALTH).setBaseValue(100);p.setHealth(100);for(int x=-8;x<=8;x++)for(int z=-8;z<=8;z++)p.level().setBlock(new net.minecraft.core.BlockPos(x,99,z),net.minecraft.world.level.block.Blocks.STONE.defaultBlockState(),3);p.teleportTo(0,100,0);p.getFoodData().setFoodLevel(20);p.getFoodData().setSaturation(20);p.getPersistentData().putBoolean("skill_overhaul_v1",true);p.getPersistentData().putBoolean("utilities_v1_migrated",true);p.getPersistentData().putBoolean("defense_v2_refunded",true);var c=SkillsAPI.getCategory(Utilities.CATEGORY).orElseThrow();c.unlock(p);c.resetSkills(p);c.setExtraPoints(p,1000);for(var id:List.of("h8krq290mbf4dwdx","nu1hd3hh115xcpax"))c.getSkill(id).orElseThrow().unlock(p);for(var id:Utilities.PATHS.get(0))c.getSkill(id).orElseThrow().unlock(p);c.openScreen(p);});step();return;}
  if(phase==1){check(screen!=null,"Native Adventurer tree opened on connected client");view(.35f,0,135);check(Math.abs(Utilities.stat(mc.player,"food")-.14)<.00001,"Fitness allocation and attributes synchronized");step();return;}
  if(phase==2){Screenshot.grab(mc,false);view(.4f,122,20);step();return;}
  if(phase==3){Screenshot.grab(mc,false);step();return;}
  if(phase==4){mc.setScreenAndShow(null);server(p->{var c=SkillsAPI.getCategory(Utilities.CATEGORY).orElseThrow();c.resetSkills(p);c.getSkill("ad8qet8e75ys5sek").orElseThrow().unlock(p);for(var id:DefenseV2.PATHS.get(2))c.getSkill(id).orElseThrow().unlock(p);check(DefenseV2.mastery(p,2),"Server selected Bulwark mastery");check(p.getAttributeValue(Attributes.ARMOR)>=4,"Server Bulwark armor="+p.getAttributeValue(Attributes.ARMOR));var helmet=new ItemStack(Items.DIAMOND_HELMET);helmet.enchant(p.registryAccess().lookupOrThrow(net.minecraft.core.registries.Registries.ENCHANTMENT).get(Identifier.parse("combat_roll:multi_roll")).orElseThrow(),3);p.setItemSlot(EquipmentSlot.HEAD,helmet);});step();return;}
  if(phase==5){check(mc.player.getAttributeValue(Attributes.ARMOR)>=4,"Defense stats synchronized actual="+mc.player.getAttributeValue(Attributes.ARMOR)+" hp="+mc.player.getHealth());check(mc.player.getAttributeValue(net.minecraft.core.registries.BuiltInRegistries.ATTRIBUTE.get(Identifier.parse("combat_roll:count")).orElseThrow())==3,"Equipped Multi Roll III grants exactly two extra rolls");mc.setScreenAndShow(null);server(p->{p.removeAllEffects();p.addEffect(new MobEffectInstance(PaladinRevamp.effect("rogues:stealth"),300));p.setSprinting(true);});step();return;}
  if(phase==6){check(mc.player.hasEffect(PaladinRevamp.effect("rogues:stealth")),"Base Vanish persists while sprinting and synchronizes");server(p->{p.setSprinting(true);check(p.isSprinting(),"Base Vanish permits sprinting on server");var proxy=(net.combat_roll.api.event.Event.Proxy)net.combat_roll.api.event.ServerSideRollEvents.PLAYER_START_ROLLING;proxy.handlers.forEach(handler->((net.combat_roll.api.event.ServerSideRollEvents.PlayerStartRolling)handler).onPlayerStartedRolling(p,new net.minecraft.world.phys.Vec3(0,0,1)));check(p.hasEffect(PaladinRevamp.effect("rogues:stealth")),"Native roll event does not end base Vanish");});step();return;}
  if(phase==7){check(mc.player.hasEffect(PaladinRevamp.effect("rogues:stealth")),"Base Vanish remains visible to client after roll event");server(p->{p.removeAllEffects();p.teleportTo(0,100,0);p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Items.IRON_SWORD));var target=EntityTypes.ZOMBIE.create(p.level(),EntitySpawnReason.COMMAND);target.setPos(0,100,6);target.setNoAi(true);target.setNoGravity(true);p.level().addFreshEntity(target);var h=PaladinRevamp.spell(p,"rogues:shadow_step");var owner=(SpellContainerSource.Owner)p;var previous=owner.getSpellContainers();owner.setSpellContainers(new SpellContainerSource.Result(previous.activeContainer(),List.of(h),List.of(),List.of(),List.of(new SpellContainerSource.SourcedContainer("probe",ItemStack.EMPTY,new net.spell_engine.api.spell.container.SpellContainer(net.spell_engine.api.spell.container.SpellContainer.ContentType.ANY,"","",0,List.of("rogues:shadow_step"))))));owner.spellModifierCache().clear();((SpellCaster.Player)p).getCooldownManager().reset(null);SpellExecution.performSpell(p.level(),p,h,new SpellTarget.SearchResult(List.of(target),null),SpellCast.Action.RELEASE,1);check(p.distanceTo(target)<3,"Actual Shadowstep teleports to its enemy");check(target.hasEffect(PaladinRevamp.effect("archers:entangling_roots")),"Actual Shadowstep roots selected enemy");check(target.getEffect(PaladinRevamp.effect("archers:entangling_roots")).getDuration()==20,"Shadowstep root lasts one second");target.discard();});step();return;}
  if(phase==8)finish();
 }catch(Throwable e){e.printStackTrace();lines.add("FAIL "+e);finish();}}
}
